% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[{"name":"purpleParts","hex":"E8DEF4","reason":"Purple cells represent the first counted quantity."},{"name":"greenParts","hex":"DCEBE0","reason":"Green cells represent the second counted quantity."},{"name":"operationBlue","hex":"268CFF","reason":"Matched arrows identify the same scaling operation on both ratio parts."}],"reference":"page 10 p10-equivalent-ratios-diagram"}
\begin{tikzpicture}[x=10mm,y=10mm,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{purpleParts}{HTML}{E8DEF4}
\definecolor{greenParts}{HTML}{DCEBE0}
\definecolor{operationBlue}{HTML}{268CFF}
\foreach \y/\rows in {3.0/1,1.6/2,0.2/4}{
  \fill[purpleParts] (0,\y) rectangle (2,\y+1);
  \fill[greenParts] (2,\y) rectangle (5,\y+1);
  \draw[black,line width=0.8pt] (0,\y) rectangle (5,\y+1);
  \foreach \x in {1,2,3,4}{\draw[black,line width=0.8pt] (\x,\y)--(\x,\y+1);}
  \ifnum\rows=2 \draw[black,line width=0.8pt] (0,\y+0.5)--(5,\y+0.5);\fi
  \ifnum\rows=4 \foreach \h in {0.25,0.5,0.75}{\draw[black,line width=0.8pt] (0,\y+\h)--(5,\y+\h);}\fi
}
\node[black,anchor=south] at (7.1,3.9) {Purple parts to green parts};
\node[black] (top) at (7.1,3.5) {$2:3$};
\node[black] (mid) at (7.1,2.1) {$4:6$};
\node[black] (bot) at (7.1,0.7) {$8:12$};
\draw[operationBlue,line width=0.8pt,->] (mid.west) to[out=180,in=180,looseness=1.5] node[left] {$\div2$} (top.west);
\draw[operationBlue,line width=0.8pt,->] (mid.east) to[out=0,in=0,looseness=1.5] node[right] {$\div2$} (top.east);
\draw[operationBlue,line width=0.8pt,->] (mid.west) to[out=180,in=180,looseness=1.5] node[left] {$\times2$} (bot.west);
\draw[operationBlue,line width=0.8pt,->] (mid.east) to[out=0,in=0,looseness=1.5] node[right] {$\times2$} (bot.east);
\end{tikzpicture}

